import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAXN = 1 << 20;
    static int n;
    static int[] f_arr = new int[MAXN], g_arr = new int[MAXN];
    static int[][] p = new int[2 * MAXN][];
    static int[][] idx_map = new int[2][MAXN];
    static int[] rev_mask = new int[MAXN];
    static int[] match = new int[21];
    static int[][] adj = new int[21][21];

    static int power(int base, int exp) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return (int) res;
    }

    static void compute(int[] f, List<Integer> left, List<Integer> right, List<Integer> subgraph, int[] idx) {
        List<Pair> edges = new ArrayList<>();
        for (int x : left) {
            for (int y : right) {
                edges.add(new Pair(x, y));
            }
        }
        int edgesSize = edges.size();
        int totalMasks = 1 << edgesSize;
        for (int mask = 0; mask < totalMasks; mask++) {
            int prob = 1;
            for (int i = 0; i < edgesSize; i++) {
                if (((mask >> i) & 1) == 1) {
                    prob = (int) ((long) prob * p[edges.get(i).first][edges.get(i).second] % MOD);
                    adj[edges.get(i).first][edges.get(i).second] = 1;
                } else {
                    prob = (int) ((long) prob * (MOD + 1 - p[edges.get(i).first][edges.get(i).second]) % MOD);
                    adj[edges.get(i).first][edges.get(i).second] = 0;
                }
            }
            for (int g : subgraph) {
                List<Integer> perm = new ArrayList<>(left);
                List<Integer> indices = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (((g >> i) & 1) == 1) {
                        indices.add(i + n);
                    }
                }
                boolean found = false;
                do {
                    boolean valid = true;
                    for (int i = 0; i < perm.size(); i++) {
                        if (adj[perm.get(i)][indices.get(i)] == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        found = true;
                        break;
                    }
                } while (nextPermutation(indices));
                if (found) {
                    int maskIdx = idx[g];
                    rev_mask[mask] |= (1 << maskIdx);
                }
            }
            f[0] = (f[0] + prob) % MOD;
        }
    }

    static boolean nextPermutation(List<Integer> seq) {
        int i = seq.size() - 2;
        while (i >= 0 && seq.get(i) >= seq.get(i + 1))
            i--;
        if (i < 0)
            return false;
        int j = seq.size() - 1;
        while (seq.get(j) <= seq.get(i))
            j--;
        Collections.swap(seq, i, j);
        int left = i + 1, right = seq.size() - 1;
        while (left < right) {
            Collections.swap(seq, left, right);
            left++;
            right--;
        }
        return true;
    }

    static class Pair {
        int first, second;
        Pair(int f, int s) {
            first = f;
            second = s;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        n = Integer.parseInt(br.readLine());
        p = new int[2 * n][];
        for (int i = 0; i < n; i++) {
            p[i] = new int[2 * n];
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(st.nextToken());
                p[i][j + n] = (int) ((long) val * power(100, MOD - 2) % MOD);
            }
        }

        if (n == 1) {
            System.out.println(p[0][n]);
            return;
        }

        int sizeA = n / 2;
        int sizeB = n - sizeA;

        int countA = 0, countB = 0;
        List<Integer> subsetA = new ArrayList<>();
        List<Integer> subsetB = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            if (Integer.bitCount(mask) == sizeA) {
                idx_map[0][mask] = countA++;
                subsetA.add(mask);
            }
            if (Integer.bitCount(mask) == sizeB) {
                idx_map[1][mask] = countB++;
                subsetB.add(mask);
            }
        }

        for (int i = 0; i < subsetB.size(); i++) {
            int mask = subsetB.get(i);
            for (int big_mask = 0; big_mask < (1 << countB); big_mask++) {
                if (((big_mask >> i) & 1) == 1) {
                    int key = (1 << n) - 1 - mask;
                    rev_mask[big_mask] |= (1 << idx_map[0][key]);
                }
            }
        }

        List<Integer> left1 = new ArrayList<>();
        List<Integer> left2 = new ArrayList<>();
        List<Integer> right_nodes = new ArrayList<>();
        for (int i = n; i < 2 * n; i++) {
            right_nodes.add(i);
        }
        for (int i = 0; i < sizeA; i++) {
            left1.add(i);
        }
        for (int i = sizeA; i < n; i++) {
            left2.add(i);
        }

        compute(f_arr, left1, right_nodes, subsetA, idx_map[0]);
        compute(g_arr, left2, right_nodes, subsetB, idx_map[1]);

        for (int i = 0; i < countA; i++) {
            for (int mask = 0; mask < (1 << countA); mask++) {
                if (((mask >> i) & 1) == 1) {
                    f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;
                }
            }
        }

        long total = 0;
        int fullMaskA = (1 << countA) - 1;
        for (int mask = 1; mask < (1 << countB); mask++) {
            int w = (1 - f_arr[fullMaskA - rev_mask[mask]] + MOD) % MOD;
            total = (total + (long) w * g_arr[mask]) % MOD;
        }

        System.out.println(total);
    }
}

